WITH unpacked AS (SELECT id, service, status_code, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text FROM app_logs WHERE service = 'checkout') SELECT id, service, status_code, retry_count, duration_text, RANK() OVER (PARTITION BY service ORDER BY retry_count DESC NULLS FIRST) AS retry_count_rank, NTILE(10) OVER (PARTITION BY service ORDER BY status_code DESC, id) AS status_code_bucket FROM unpacked;
